$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot 'resolve-node.ps1');$root=[System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$node=Resolve-ResearchNode;$checks=@();function Add([string]$Name,[bool]$Passed,[string]$Evidence){$script:checks += [ordered]@{name=$Name;passed=$Passed;evidence=$Evidence}};$version=& $node --version;Add 'node' ($LASTEXITCODE -eq 0) $version;foreach($file in @('package.json','schemas\routing-manifest.schema.json','benchmark\task-suite.mjs','AGENTS.md')){Add "file:$file" (Test-Path -LiteralPath (Join-Path $root $file)) (Join-Path $root $file)};$passed=-not($checks|Where-Object{-not $_.passed});$summary=[ordered]@{schemaVersion=1;passed=$passed;checks=$checks;generatedAt=(Get-Date).ToUniversalTime().ToString('o')};$output=Join-Path $root 'reports\autonomy-doctor.json';$summary|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $output -Encoding utf8;$summary|ConvertTo-Json -Depth 6 -Compress;if(-not $passed){exit 1}
